import { test, expect } from '@playwright/test';

test.describe('Checkout Form Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should accept valid card expiry date in MM/YY format', async ({ page }) => {
    await page.fill(getByLabel('Card Expiry'), '12/25');
    await page.click(getByRole('button', { name: 'Submit' }));
    await expect(page.getByText('Payment processed successfully')).toBeVisible();
  });

  test('should show error for invalid card expiry date', async ({ page }) => {
    await page.fill(getByLabel('Card Expiry'), '13/25');
    await page.click(getByRole('button', { name: 'Submit' }));
    await expect(page.getByText('Invalid expiry date')).toBeVisible();
  });
});
